var preorderTraversal = function(root) {
    if (!root) {
        return [];
    }

    const stack = [root];
    const result = [];

    while (stack.length) {
        const node = stack.pop();
        result.push(node.val);

        // Push right first so left gets processed first (LIFO order)
        if (node.right) {
            stack.push(node.right);
        }

        if (node.left) {
            stack.push(node.left);
        }
    }

    return result;
};
